use js_runtime::{Runtime,Value};use js_runtime::property_slots::LiteralReadSite;use std::hint::black_box;static LENGTH:LiteralReadSite=LiteralReadSite::new("length");
fn main(){for kind in["array","string","boxed"]{for trial in 0..7{for enabled in if trial%2==0{[false,true]}else{[true,false]}{let mut rt=Runtime::new();rt.literal_length_fast_path_enabled=enabled;let text=rt.string_utf16(&[97,0xd800,0xdc00,0xdfff]);let value=match kind{"array"=>rt.array(&[None,None,None,None]),"string"=>text,_=>rt.to_object(text).unwrap()};assert_eq!(rt.get_literal_cached(value,&LENGTH).unwrap(),Value::Number(4.0));let start=std::time::Instant::now();for _ in 0..500_000{black_box(rt.get_literal_cached(black_box(value),&LENGTH).unwrap());}println!("{kind}\t{trial}\t{enabled}\t{}",start.elapsed().as_nanos());}}}}
